#include <stdio.h>
/*
 * ex03：常用等值式批量验证
 * 为什么：等值演算题全靠这几条律，但「记错一条」在考场上就是整题崩。
 *        与其背，不如让程序把每一条在全部赋值下跑一遍 —— 恒等就是律，不等就有反例。
 */
static int imp(int a, int b) { return (!a) || b; }
static int iff(int a, int b) { return a == b; }

int main(void) {
    const char *names[] = {
        "p->q == ~p v q",
        "~(p^q) == ~p v ~q   (De Morgan)",
        "~(p v q) == ~p ^ ~q (De Morgan)",
        "p<->q == (p->q)^(q->p)",
        "p v (p^q) == p       (absorption)",
        "~~p == p             (double negation)",
        "p^(q v r) == (p^q)v(p^r) (distributive)"
    };
    int ok[7] = {1, 1, 1, 1, 1, 1, 1};
    for (int p = 0; p < 2; p++)
        for (int q = 0; q < 2; q++)
            for (int r = 0; r < 2; r++) {
                if (imp(p, q) != ((!p) || q)) ok[0] = 0;
                if ((!(p && q)) != ((!p) || (!q))) ok[1] = 0;
                if ((!(p || q)) != ((!p) && (!q))) ok[2] = 0;
                if (iff(p, q) != (imp(p, q) && imp(q, p))) ok[3] = 0;
                if ((p || (p && q)) != p) ok[4] = 0;
                if ((!!p) != p) ok[5] = 0;
                if ((p && (q || r)) != ((p && q) || (p && r))) ok[6] = 0;
            }
    printf("%-42s %s\n", "law", "holds?");
    printf("------------------------------------------+-------\n");
    int all = 1;
    for (int i = 0; i < 7; i++) {
        printf("%-42s %s\n", names[i], ok[i] ? "yes" : "NO (counterexample exists)");
        if (!ok[i]) all = 0;
    }
    printf("\n%d/7 laws verified over all 8 assignments.\n", all ? 7 : 0);
    printf("tip: rewrite -> and <-> away first, then only ~ ^ v remain.\n");
    return 0;
}
